<script setup lang="ts">
const { t, locale } = useI18n()
const { statusLabel } = useReportLabels()
import type { ConsumerReport, LabResult } from '../../composables/useConsumer'
import { formatDisplayDate as formatDateForLocale } from '../../utils/formatDisplayDate'
function formatDisplayDate(value: string, includeTime = false) { return formatDateForLocale(value, includeTime, locale.value) }
definePageMeta({layout:'consumer'})
const {profileId,request,requireSession,apiBase,token}=useConsumer(),route=useRoute(),router=useRouter()
const report=ref<ConsumerReport|null>(null),loading=ref(true),error=ref(''),busy=ref(false),editing=ref<LabResult|null>(null),fileUrl=ref(''),fileType=ref('')
const form=reactive({parameterName:'',value:'',unit:'',sampleDate:'',referenceRange:''})
useHead({title:'Report detail | Doclyzer'})
async function load(){loading.value=true;error.value='';try{const r=await request<ConsumerReport>(`/reports/${encodeURIComponent(String(route.params.id))}`);if(r.profileId!==profileId.value){await router.replace('/reports');return}report.value=r}catch(cause){error.value=(cause as Error).message}finally{loading.value=false}}
onMounted(async()=>{if(await requireSession())await load()})
watch(profileId,()=>{report.value=null;router.replace('/reports')})
function edit(row:LabResult){editing.value=row;Object.assign(form,{parameterName:row.parameterName,value:row.value,unit:row.unit??'',sampleDate:row.sampleDate??'',referenceRange:row.referenceRange??''})}
async function save(){if(!report.value||!editing.value)return;busy.value=true;error.value='';try{report.value=await request<ConsumerReport>(`/reports/${report.value.id}/results/${editing.value.id}`,{method:'PATCH',body:{expectedVersion:editing.value.reviewVersion,...form,unit:form.unit||null,sampleDate:form.sampleDate||null,referenceRange:form.referenceRange||null}});editing.value=null}catch(cause){const message=(cause as Error).message;if((cause as {statusCode?:number}).statusCode===409){await load();editing.value=null;error.value='This result changed elsewhere. Review the latest value before editing again.'}else error.value=message}finally{busy.value=false}}
async function original(){if(!report.value)return;busy.value=true;error.value='';try{const blob=await $fetch<Blob>(`${apiBase}/reports/${report.value.id}/file`,{responseType:'blob',headers:{Authorization:`Bearer ${token.value}`}});if(fileUrl.value)URL.revokeObjectURL(fileUrl.value);fileUrl.value=URL.createObjectURL(blob);fileType.value=report.value.contentType}catch(cause){error.value=(cause as Error).message}finally{busy.value=false}}
onBeforeUnmount(()=>{if(fileUrl.value)URL.revokeObjectURL(fileUrl.value)})
</script>
<template><div><NuxtLink to="/reports">{{ t('backReports') }}</NuxtLink><p v-if="loading" role="status">{{ t('loadingReport') }}</p><p v-if="error" role="alert" class="alert error">{{ error }}</p><template v-if="report"><header class="page-heading"><div><p class="eyebrow">{{ statusLabel(report.status) }}</p><h1>{{ report.originalFileName }}</h1><p class="muted">{{ report.collectionDate ? t('collectedOn', { date: formatDisplayDate(report.collectionDate) }) : t('unknownCollection') }} · {{ t('uploadedOn', { date: formatDisplayDate(report.createdAt) }) }}</p></div><button class="secondary" :disabled="busy" @click="original">{{ t('openOriginal') }}</button></header><div v-if="report.processingState && report.processingState!=='ready'" class="alert">{{ t('processingReport', { status: statusLabel(report.processingState) }) }}</div><section v-if="report.summary" class="card"><h2>{{ t('summary') }}</h2><ReportsLocalizedSummary :report-id="report.id" :summary="report.summary" /><AiDisclaimerNote /></section><section class="card"><h2>{{ t('extractedResults') }}</h2><p class="muted">{{ t('checkResultsHelp') }}</p><p v-if="!report.extractedLabValues.length">{{ t('noResultsYet') }}</p><article v-for="row in report.extractedLabValues" :key="row.id" class="result row"><div><h3>{{ row.parameterName }}</h3><p><strong>{{ row.value }} {{ row.unit }}</strong> · {{ row.referenceRange ? t('labRangeValue', { range: row.referenceRange }) : t('rangeUnavailable') }}</p><p>{{ row.referenceRange && typeof row.isAbnormal === 'boolean' ? (row.isAbnormal ? t('outsideRange') : t('insideRange')) : t('comparisonUnavailable') }}</p><p class="muted">{{ row.sampleDate ? formatDisplayDate(row.sampleDate) : t('unknownCollection') }} · {{ statusLabel(row.reviewState ?? 'unreviewed') }}</p></div><div class="actions"><NuxtLink class="button secondary" :to="`/trends/${encodeURIComponent(row.parameterName)}?reportId=${report.id}`">{{ t('viewTest') }}</NuxtLink><button class="secondary" @click="edit(row)">{{ t('correct') }}</button></div></article></section><ReportsVlShadowReview :report-id="report.id" :content-type="report.contentType" @applied="load" /><section v-if="editing" class="card"><h2>{{ t('correctResult') }}</h2><p>{{ t('checkBeforeSave') }}</p><form class="stack" @submit.prevent="save"><label class="field">{{ t('testName') }}<input v-model="form.parameterName" required maxlength="256" /></label><div class="grid"><label class="field">{{ t('value') }}<input v-model="form.value" required maxlength="512" /></label><label class="field">{{ t('unit') }}<input v-model="form.unit" maxlength="64" /></label><label class="field">{{ t('collectionDate') }}<input v-model="form.sampleDate" type="date" /></label><label class="field">{{ t('labReferenceRange') }}<input v-model="form.referenceRange" maxlength="256" /></label></div><div class="actions"><button :disabled="busy">{{ t('saveCorrection') }}</button><button type="button" class="secondary" @click="editing=null">{{ t('cancel') }}</button></div></form></section></template><div v-if="fileUrl" class="viewer" role="dialog" aria-modal="true" :aria-label="t('originalReport')"><div class="row"><strong>{{ t('originalReport') }}</strong><button @click="URL.revokeObjectURL(fileUrl);fileUrl=''">{{ t('close') }}</button></div><img v-if="fileType.startsWith('image/')" :src="fileUrl" alt="Original lab report" /><iframe v-else :src="fileUrl" title="Original lab report" /></div></div></template>
<style scoped>.result{border-top:1px solid #e2e9e1;padding:16px 0}.result h3,.result p{margin:0 0 6px}.viewer{position:fixed;inset:2%;z-index:30;background:white;padding:16px;border-radius:15px;box-shadow:0 0 0 100vmax #123629b9;display:flex;flex-direction:column}.viewer img,.viewer iframe{width:100%;flex:1;min-height:0;object-fit:contain;border:0}@media(max-width:600px){.page-heading{display:block}.result{display:block}}</style>
